from datetime import date, timedelta
from typing import Dict, Optional, Set


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books: Set[str] = set()
        # Maps book_id to (user, borrow_date)
        self.loans: Dict[str, tuple[str, date]] = {}
        # Maps user to their current unpaid fines
        self.fines: Dict[str, float] = {}

    def add_book(self, book_id: str) -> None:
        self.books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError(f"Book '{book_id}' does not exist in library.")

        if book_id in self.loans:
            raise ValueError(f"Book '{book_id}' is already borrowed.")

        # Check user's current active loans
        user_active_loans = sum(
            1 for borrower, _ in self.loans.values() if borrower == user
        )

        # Requirement 4: A user with unpaid fines may hold at most one book at a time
        if self.unpaid_fines(user) > 0 and user_active_loans >= 1:
            raise ValueError(
                f"User '{user}' has unpaid fines and cannot borrow more than one book."
            )

        self.loans[book_id] = (user, day)

    def return_book(self, user: str, book_id: str, day: date) -> float:
        """Return a book; returns the fine charged for this return."""
        if book_id not in self.loans:
            raise ValueError(f"Book '{book_id}' is not currently borrowed.")

        borrower, borrow_day = self.loans[book_id]
        if borrower != user:
            raise ValueError(
                f"Book '{book_id}' was not borrowed by user '{user}'."
            )

        # Calculate due date: borrow day plus loan_days
        due_date = borrow_day + timedelta(days=self.loan_days)

        # Calculate delay days excluding Saturdays (5) and Sundays (6)
        chargeable_days = 0
        current_day = due_date + timedelta(days=1)
        while current_day <= day:
            if current_day.weekday() < 5:  # Monday to Friday
                chargeable_days += 1
            current_day += timedelta(days=1)

        fine = chargeable_days * self.daily_fine
        if fine > 0:
            self.fines[user] = self.fines.get(user, 0.0) + fine

        # Remove the book from active loans
        del self.loans[book_id]

        return fine

    def unpaid_fines(self, user: str) -> float:
        return self.fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        """Pay all fines of the user."""
        self.fines[user] = 0.0
```

